// 策略同步完成，生成汇总摘要
const result = $input.first().json;
const s = result.strategy;

if (!s) {
  return { summary: '无启用的最优策略，跳过同步', strategy: null };
}

const p = s.params;
let summary = '策略同步完成\n';
summary += `止盈 ${(p.take_profit*100).toFixed(0)}% | 止损 ${(p.stop_loss*100).toFixed(0)}%\n`;
summary += `仓位 ${(p.buy_ratio*100).toFixed(0)}% | 持仓 ${p.max_hold_hours}h\n`;
summary += `流动性过滤: $${p.min_liquidity_usd.toLocaleString()}\n`;
summary += `\n回测基准:\n`;
summary += `胜率 ${(s.win_rate*100).toFixed(1)}% | 收益 ${(s.backtest_profit*100).toFixed(1)}%\n`;
summary += `最大回撤 ${(s.max_drawdown*100).toFixed(1)}%\n`;
summary += `\n同步状态: ${result.message}`;

return {
  summary: summary,
  strategy: s,
  synced: result.synced,
  message: result.message
};

